        result = self.run_orchestrator('--apply')

        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(race_target.read_text(encoding='utf-8'), 'preserve\n')
        self.assertTrue(self.lock_file.is_symlink())

