    def pod_delegation_gate(
        self,
        function: str,
        permissions: str,
        errexit: str = 'off',
    ) -> subprocess.CompletedProcess[str]:
        return self.run_command(
            [
                '/bin/bash',
                '-c',
                textwrap.dedent(
                    r'''
                    set -u
                    source "$0"
                    function=$1
                    permissions=$2
                    errexit=$3
                    kubectl_run() {
                      args=("$@")
                      verb=
                      for ((index = 0; index < ${#args[@]} - 1; index++)); do
                        if [[ "${args[index]}" == can-i ]]; then
                          verb=${args[index + 1]}
                          break
                        fi
                      done
                      [[ " ${args[*]} " == *' --request-timeout=5s '* ]] ||
                        return 2
                      case "$permissions" in
                        missing-*)
                          missing=${permissions#missing-}
                          case "$verb" in
                            get|list|watch|update|patch)
                              if [[ "$verb" == "$missing" ]]; then
                                printf 'no\n'
                                return 1
                              fi
                              printf 'yes\n'
                              return 0
                              ;;
                            *)
                              printf 'no\n'
                              return 1
                              ;;
                          esac
                          ;;
                        extra-*)
                          extra=${permissions#extra-}
                          case "$verb" in
                            get|list|watch|update|patch)
                              printf 'yes\n'
                              return 0
                              ;;
                            *)
                              if [[ "$verb" == "$extra" ]]; then
                                printf 'yes\n'
                                return 0
                              fi
                              printf 'no\n'
                              return 1
                              ;;
                          esac
                          ;;
                        absent)
                          printf 'no\n'
                          return 1
                          ;;
                        exact)
                          case "$verb" in
                            get|list|watch|update|patch)
                              printf 'yes\n'
                              return 0
                              ;;
                            *)
                              printf 'no\n'
                              return 1
                              ;;
                          esac
                          ;;
                        extra)
                          case "$verb" in
                            get|list|watch|create|update|patch)
                              printf 'yes\n'
                              return 0
                              ;;
                            *)
                              printf 'no\n'
                              return 1
                              ;;
                          esac
                          ;;
                        create-only)
                          if [[ "$verb" == create ]]; then
                            printf 'yes\n'
                            return 0
                          fi
                          printf 'no\n'
                          return 1
                          ;;
                        error)
                          return 2
                          ;;
                      esac
                      return 2
                    }
                    if [[ "$errexit" == on ]]; then
                      set -e
                    else
                      set +e
                    fi
                    before=$-
                    if "openbao_helm_pod_delegation_is_${function}"; then
                      rc=0
                    else
                      rc=$?
                    fi
                    after=$-
                    [[ "$before" == "$after" ]] || exit 90
                    exit "$rc"
                    '''
                ).strip(),
                str(OPENBAO_RUNTIME_LIB),
                function,
                permissions,
                errexit,
            ],
            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
        )

    def pod_delegation_wait(
        self,
        ready_after: int,
    ) -> subprocess.CompletedProcess[str]:
        return self.run_command(
            [
                '/bin/bash',
                '-c',
                textwrap.dedent(
                    r'''
                    set -u
                    source "$0"
                    ready_after=$1
                    checks=0
                    openbao_helm_pod_delegation_is_exact() {
                      checks=$((checks + 1))
                      (( checks >= ready_after ))
                    }
                    openbao_wait_helm_pod_delegation
                    rc=$?
                    printf 'CHECKS=%s\n' "$checks"
                    exit "$rc"
                    '''
                ).strip(),
                str(OPENBAO_RUNTIME_LIB),
                str(ready_after),
            ],
            env={'PATH': '/usr/bin:/bin', 'LC_ALL': 'C'},
        )

