    def write_executable(self, path: Path, source: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(textwrap.dedent(source).lstrip(), encoding='utf-8')
        path.chmod(0o755)

    def helm_member(self) -> bytes:
        return textwrap.dedent(
            '''
            #!/usr/bin/python3 -B
            import os
            from pathlib import Path
            import signal
            import sys
            import time

            args = sys.argv[1:]
            with open(os.environ['FAKE_COMMAND_LOG'], 'a', encoding='utf-8') as log:
                log.write('helm ' + ' '.join(args) + '\\n')
            sys.stderr.write(os.environ['FAKE_CANARY'] + '\\n')
            if (
                os.environ.get('FAKE_SIMULATE_CLIENT_CACHE', '0') == '1'
                and os.environ.get('KUBECACHEDIR') != '/dev/null'
            ):
                cache = Path(os.environ['HOME']) / '.kube/cache/helm-write'
                cache.parent.mkdir(parents=True, exist_ok=True)
                cache.write_text('cache\\n', encoding='utf-8')
            if args == ['version', '--short']:
                print(os.environ.get('FAKE_HELM_VERSION', 'v3.21.0+gfixture'))
                raise SystemExit(0)
            if (
                len(args) == 11
                and args[:2] == ['template', 'cilium']
                and args[3:5] == ['--namespace', 'kube-system']
                and args[5] == '--values'
                and args[7:] == [
                    '--kube-version', 'v1.36.3',
                    '--show-only', 'templates/cilium-operator/deployment.yaml',
                ]
            ):
                checksum = os.environ.get(
                    'FAKE_RENDERED_OPERATOR_CHECKSUM', 'a' * 64
                )
                print('apiVersion: apps/v1')
                print('kind: Deployment')
                print('metadata:')
                print('  name: cilium-operator')
                print('  namespace: kube-system')
                print('spec:')
                print('  template:')
                print('    metadata:')
                print('      annotations:')
                print(
                    '        cilium.io/cilium-configmap-checksum: '
                    f'"{checksum}"'
                )
                raise SystemExit(0)
            if len(args) < 2 or args[0] != '--kubeconfig':
                raise SystemExit(64)
            try:
                supplied = Path(args[1]).read_text(encoding='utf-8')
                # 真实 helm/client-go 会多次加载 kubeconfig；管道第二次读到空。
                supplied_again = Path(args[1]).read_text(encoding='utf-8')
            except OSError:
                raise SystemExit(64)
            if supplied != os.environ['FAKE_ADMIN_CONF_CONTENT'] or supplied_again != supplied:
                raise SystemExit(64)
            if os.environ.get('FAKE_HELM_KILL_PARENT', '0') == '1':
                # 模拟运维中断：kubeconfig 临时目录还在时杀掉调用 stage 的 shell。
                os.kill(os.getppid(), signal.SIGTERM)
                time.sleep(0.5)
                raise SystemExit(0)
            expected = [
                '--kubeconfig', args[1],
                'list', '--all-namespaces', '--all', '--output', 'json',
            ]
            if args == expected:
                if os.environ.get('FAKE_HELM_LIST_FAIL', '0') == '1':
                    raise SystemExit(1)
                print(os.environ['FAKE_HELM_LIST_JSON'])
                raise SystemExit(0)
            values_prefix = [
                '--kubeconfig', args[1],
                'get', 'values', 'cilium', '--namespace', 'kube-system',
                '--revision',
            ]
            if (
                len(args) == len(values_prefix) + 3
                and args[:len(values_prefix)] == values_prefix
                and args[-2:] == ['--output', 'json']
                and args[len(values_prefix)] in {'1', '2', '3'}
            ):
                if os.environ.get('FAKE_HELM_VALUES_FAIL', '0') == '1':
                    raise SystemExit(1)
                revision = args[len(values_prefix)]
                current = os.environ.get('FAKE_HELM_REVISION', '1')
                if int(revision) > int(current):
                    raise SystemExit(1)
                override = os.environ.get(
                    f'FAKE_HELM_REVISION_{revision}_VALUES_JSON'
                )
                if override is not None:
                    sys.stdout.write(override)
                elif revision == current:
                    sys.stdout.write(os.environ['FAKE_HELM_VALUES_JSON'])
                elif revision == '1':
                    sys.stdout.write(os.environ['FAKE_HELM_LEGACY_VALUES_JSON'])
                elif revision == '2' and current == '3':
                    sys.stdout.write(
                        os.environ['FAKE_HELM_PRE_ROLLOUT_VALUES_JSON']
                    )
                else:
                    raise SystemExit(1)
                raise SystemExit(0)
            raise SystemExit(64)
            '''
        ).lstrip().encode()

    def helm_archive(self, member: bytes) -> bytes:
        stream = io.BytesIO()
        with tarfile.open(fileobj=stream, mode='w:gz') as archive:
            entry = tarfile.TarInfo('linux-amd64/helm')
            entry.mode = 0o755
            entry.size = len(member)
            archive.addfile(entry, io.BytesIO(member))
        return stream.getvalue()

